import { supabase } from '../../supabaseConfig'


export class AuthService {
    client;

    constructor(client){
        this.client = client
    }

    async uploadDocument(user, file, conversationId){
        // yeh new folder bnayega for every new upload, and will store the file in that folder. 
        // The folder name is a random UUID generated by crypto.randomUUID(). 
        // This ensures that each file is stored in a unique location, preventing overwriting of files with the same name.
        const filePath  = `${user.id}/conversations/${conversationId}/documents/${crypto.randomUUID()}-${file.name}}`;
        try{
            const {data, error} = await this.client.storage
                                            .from('kairo-private')
                                            .upload(filePath, file, {
                                                    contentType: file.type,
                                                    upsert: false,
                                            });
            console.log("Supabase service :: uploadDocument :: Successfully uploaded :: ", data.path);
            return data;
        }catch(error){
            console.log("Supabase service :: uploadDocument :: error :: ", error);
            return null;
        }
    }

    async uplaodProfilePicture(user, file){
        const filePath = `/profile-pictures/${user.id}/${crypto.randomUUID()}-${file.name}`;
        try{
            const {data, error} = await this.client.storage
                                            .from('kairo-public')
                                            .upload(filePath, file, {
                                                    contentType: file.type,
                                                    upsert: true,     
                                            });
            console.log("Supabase service :: uploadProfilePicture :: Successfully uploaded :: ", data.path);
            return data;
        }catch(error){
            console.log("Supabase service :: uploadProfilePicture :: error :: ", error);
            return null;
        }
    }

    
}